            if v['http']!=200 or dd.get('exitState')!='OK' or dd.get('responseCode')!=0: print('CHG',cn,card,w,v['http'],json.dumps(r)[:300])
    for card,v in (s.get('cards.balance') or {}).items():
        dd=v.get('response',{}).get('data',{})
        if not dd: print('BAL-ERR',cn,card,v['http']); continue
        flags=[]
        if not dd.get('statementDate'): flags.append('noStmtDate')
        if dd.get('automaticPaymentFlag')=='Y': flags.append('AUTO')
        for c in ('debtTL','debtUSD','debtEUR','debtGBP'):
            b=dd.get(c)
            if b is None: flags.append('missing'+c); continue
            if b.get('transferAmount',0)>0: flags.append('transfer'+c)
            if b.get('totalDebt',0)<0 or b.get('remainingDebt',0)<0: flags.append('neg'+c)
            if b.get('remainAutomaticPaymentAmount',0)>0: flags.append('remAuto'+c)
        print('BAL',cn,card,repr(dd.get('productName')),dd.get('statementDate'),dd.get('lastPayDate'),dd.get('nextStatementDate'),dd.get('statementPaymentStatus'),flags)
