    elif wants_all:
        fail += 1
        prompt = 'Borç bilgisini tek seferde yalnızca bir kart için verebiliyorum. ' + examples_question(el)
    elif how == 'generic' and len(el) > 1:
        vars['sel_stage'] = 'last4'
        vars['sel_cands'] = json.dumps([c['n'] for c in el])
